import json
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
drafts = {}


def add(number, paragraphs, reason, review_notes):
    assert number not in drafts
    drafts[number] = {
        'proposed_xml': '\n'.join(f'<p>{p}</p>' for p in paragraphs),
        'reason': reason,
        'review_notes': review_notes,
    }


add('L302-9-1-1', [
    "I.- Une commission nationale est placée auprès du ministre chargé du logement. Une personnalité qualifiée désignée par ce ministre la préside. Elle comprend deux députés et deux sénateurs, un membre de la juridiction administrative, un magistrat de la Cour des comptes ou des chambres régionales des comptes, en activité ou honoraire, un agent exerçant des fonctions d'inspection générale au sein de l'inspection générale de l'environnement et du développement durable, des représentants des associations nationales représentatives des élus locaux, de l'Union nationale des fédérations d'organismes d'habitations à loyer modéré et du Haut Comité pour le logement des personnes défavorisées et le suivi du droit au logement opposable, ainsi que des représentants des associations et organisations œuvrant dans le domaine du logement des personnes défavorisées, désignés par le Conseil national de l'habitat.",
    "La commission motive ses avis et les rend publics.",
    "II.- Dans le cadre du bilan triennal, avant que les représentants de l'État dans les départements signent les arrêtés de carence dans les conditions définies à l'article L. 302-9-1, la commission nationale peut obtenir communication de tous les documents utiles et solliciter les avis qu'elle juge nécessaires. Ces documents et avis lui permettent d'apprécier la pertinence d'un projet d'arrêté de carence ou de l'absence d'un tel projet, ainsi que la bonne prise en compte des orientations nationales définies par le ministre chargé du logement. Dans ce cadre, elle peut, de sa propre initiative ou sur saisine du comité régional de l'habitat et de l'hébergement, adresser des avis et des recommandations aux représentants de l'État dans les départements. Elle transmet ses avis au ministre chargé du logement.<br/><br/>Avant de rendre l'avis sur l'exemption d'une commune des dispositions de la présente section, en application du second alinéa du III de l'article L. 302-5, la commission nationale peut obtenir communication de tous les documents utiles et solliciter les avis qu'elle juge nécessaires à son appréciation. Elle transmet ses avis au ministre chargé du logement.",
    "Avant la conclusion des contrats de mixité sociale dans les conditions prévues à l'article L. 302-8-1, la commission nationale peut obtenir communication de tous les documents utiles et solliciter les avis qu'elle juge nécessaires à son appréciation. Elle transmet ses avis au ministre chargé du logement.",
    "III.- La composition de la commission prévue au présent article est définie par décret en Conseil d'État.",
], "Réécriture à droit constant : la désignation de la présidence et les obligations de motivation et de publicité deviennent des phrases autonomes. Les trois cadres d'intervention de la commission sont explicités sans modifier sa composition ni ses pouvoirs. Aucune réforme de fond n'est introduite.",
    "Conserver la composition, les deux députés et deux sénateurs, les saisines et les renvois à L. 302-9-1, au second alinéa du III de L. 302-5 et à L. 302-8-1. La note source fixe l'entrée en vigueur historique au 1er septembre 2022, conformément à l'article 8 du décret n° 2022-1025 du 20 juillet 2022 ; elle ne date pas la réforme proposée. Les contrats de mixité sociale et les avis de la commission ne suppriment pas les obligations de logement social.")

add('L302-9-1-2', [
    "Dans les communes faisant l'objet d'un arrêté pris au titre de l'article L. 302-9-1, toute opération de construction d'immeubles collectifs de plus de douze logements ou de plus de 800 mètres carrés de surface de plancher doit comprendre, parmi ses logements familiaux, au moins 30 % de logements locatifs sociaux définis à l'article L. 302-5, à l'exclusion des logements financés par un prêt locatif social. Sur demande motivée de la commune, le représentant de l'État peut déroger à cette obligation pour tenir compte de la typologie des logements situés à proximité de l'opération.",
    "L'obligation prévue au premier alinéa du présent article ne s'applique pas aux opérations soumises à autorisation d'urbanisme qui réalisent, sur des terrains affectés aux besoins du ministère de la défense, des logements destinés aux agents de ce ministère.",
], "Réécriture à droit constant : l'opération devient le sujet de l'obligation et le calcul de la proportion sur les logements familiaux est rendu explicite. La dérogation préfectorale et l'exception de la défense restent distinctes. Aucune réforme de fond n'est apportée.",
    "Seuils alternatifs strictement supérieurs à douze logements ou à 800 mètres carrés, proportion minimale de 30 % et exclusion des prêts locatifs sociaux conservés. Le second alinéa conserve sa place et les deux conditions cumulatives de l'exception : terrains affectés à la défense et logements destinés à ses agents. Aucune convention locale ne remplace cette obligation.")

add('L302-9-2', [
    "Les conditions d'application du présent chapitre sont fixées, en tant que de besoin, par décret en Conseil d'État. Ce décret prévoit notamment les conditions rendues nécessaires par la situation particulière de la Guadeloupe, de la Guyane, de la Martinique, de La Réunion, de Mayotte et de Saint-Martin.",
], "Réécriture à droit constant : la règle de compétence réglementaire et les adaptations territoriales sont énoncées en deux phrases. La réserve tenant au besoin de mesures d'application est conservée. Aucune réforme de fond.",
    "Le décret demeure un décret en Conseil d'État et vise tout le chapitre. Les six territoires énumérés sont conservés, sans extension à d'autres collectivités.")

add('L302-10', [
    "Un plan départemental de l'habitat est élaboré dans chaque département. Il assure la cohérence entre les politiques de l'habitat conduites dans les territoires couverts par un programme local de l'habitat et celles conduites dans le reste du département.",
    "Le plan définit ses orientations en conformité avec celles des schémas de cohérence territoriale et des programmes locaux de l'habitat. Il prend également en compte les besoins définis par le plan départemental d'actions pour le logement des personnes défavorisées et les besoins des personnes en perte d'autonomie définis par le schéma départemental d'organisation sociale et médico-sociale prévu à l'article L. 312-4 du code de l'action sociale et des familles. Il prend aussi en compte les objectifs de la programmation pluriannuelle de financement de l'habitat inclusif mentionnée à l'article L. 281-2-1 du même code.",
    "Le plan comprend un diagnostic du fonctionnement des marchés du logement. Il définit les conditions de mise en place d'un dispositif départemental d'observation de l'habitat.",
], "Réécriture à droit constant : les fonctions de cohérence, les documents à prendre en compte et le diagnostic sont répartis en phrases plus courtes, en conservant les trois alinéas. Aucune réforme de fond.",
    "La conformité aux orientations des schémas de cohérence territoriale et des programmes locaux demeure distincte de la prise en compte des besoins et objectifs sociaux. Renvois L. 312-4 et L. 281-2-1 du CASF conservés. La dénomination source « plan départemental d'actions pour le logement des personnes défavorisées » diffère de celle employée à L. 303-1, qui mentionne aussi l'hébergement : vérifier cette terminologie sans la modifier silencieusement.")

add('L302-11', [
    "L'État, le département et les établissements publics de coopération intercommunale qui ont adopté un programme local de l'habitat ou délibéré pour en engager l'élaboration élaborent conjointement le plan départemental de l'habitat, pour une durée de six ans.",
], "Réécriture à droit constant : les auteurs du plan sont placés en sujet de la phrase et les deux catégories d'établissements participants sont exprimées directement. La durée du plan reste inchangée ; aucune réforme de fond.",
    "Durée de six ans conservée. La participation couvre aussi les établissements ayant seulement délibéré pour engager l'élaboration du programme local de l'habitat ; elle n'est pas limitée à ceux ayant déjà adopté ce programme.")

add('L302-12', [
    "Une section départementale du comité régional de l'habitat et de l'hébergement visé à l'article L. 364-1 mène les concertations nécessaires à l'élaboration du plan départemental de l'habitat et de l'hébergement. Le représentant de l'État dans le département et le président du conseil départemental président conjointement cette section. En Corse, cette présidence conjointe est assurée par le représentant de l'État dans le département et le président du conseil exécutif.",
], "Réécriture à droit constant : l'organisme chargé de la concertation est identifié en début de phrase et la règle particulière à la Corse est isolée. Aucune modification des compétences ni réforme de fond.",
    "Renvoi à L. 364-1 et coprésidence conservés. La source désigne ici un « plan départemental de l'habitat et de l'hébergement », alors que L. 302-10 et L. 302-11 parlent d'un « plan départemental de l'habitat » : divergence préexistante à coordonner expressément, non corrigée dans la proposition.")

add('L302-13', [
    "I.- Depuis le 1er juillet 2014, le comité régional de l'habitat et de l'hébergement d'Ile-de-France assure la cohérence des politiques de l'habitat et de l'hébergement en Ile-de-France.",
    "Le comité régional de l'habitat et de l'hébergement d'Ile-de-France comprend cinq collèges, composés respectivement :",
    "1° De représentants de l'État ;",
    "2° De représentants de la région d'Ile-de-France et des départements franciliens ;",
    "3° De représentants de la métropole du Grand Paris ou, dans l'attente de sa création, des communes et groupements de communes de son territoire, ainsi que des groupements de communes situés hors du périmètre de la métropole ;",
    "4° De professionnels et de représentants des associations intervenant dans les domaines du logement, de l'immobilier, de la construction ou de la mise en œuvre des moyens financiers correspondants ;",
    "5° De représentants d'organismes intervenant dans l'accueil, le soutien, l'hébergement, l'accompagnement, l'insertion ou la défense des personnes en situation d'exclusion, d'organisations d'usagers, des personnes prises en charge par le dispositif d'accueil, d'hébergement et d'accompagnement vers l'insertion et le logement, de bailleurs privés, des partenaires sociaux associés à la gestion de la participation des employeurs à l'effort de construction et de personnalités qualifiées.",
    "Le représentant de l'État dans la région et le président du conseil régional d'Ile-de-France, ou le représentant de ce dernier, assurent la présidence du comité régional de l'habitat et de l'hébergement d'Ile-de-France.",
    "Un décret en Conseil d'État précise la composition du comité régional de l'habitat et de l'hébergement d'Ile-de-France, les modalités de désignation de ses membres et ses règles de fonctionnement.",
    "II.- Le comité régional de l'habitat et de l'hébergement d'Ile-de-France élabore un schéma régional de l'habitat et de l'hébergement à partir d'un diagnostic du logement et de l'habitat. En cohérence avec l'objectif fixé à l'article 1er de la loi n° 2010-597 du 3 juin 2010 relative au Grand Paris, ce schéma fixe, pour six ans, les objectifs globaux en matière de construction et de rénovation de logements, de construction et d'amélioration des structures d'hébergement, de développement équilibré du parc de logements sociaux, de rénovation thermique des logements, d'actions en faveur des populations défavorisées, de rénovation urbaine, de requalification des quartiers anciens dégradés et de lutte contre l'habitat indigne. Il décline territorialement ces objectifs au niveau de chaque établissement public de coopération intercommunale, dans le respect des orientations du schéma directeur de la région d'Ile-de-France.",
    "Le schéma prévoit les critères, les indicateurs et les modalités de suivi de l'application de ses dispositions et de leurs incidences. En prenant en compte les actions de rénovation urbaine au sens de la loi n° 2003-710 du 1er août 2003 d'orientation et de programmation pour la ville et la rénovation urbaine, il indique les objectifs à atteindre pour satisfaire les besoins en logements et en places d'hébergement. Il précise notamment :",
    "1° L'offre nouvelle et la typologie des logements à construire, au regard de l'évaluation des besoins. Cette typologie précise notamment l'offre de logements locatifs sociaux ;",
    "2° Les actions à conduire pour améliorer et réhabiliter le parc de logements existant, privé et public ;",
    "3° Les réponses aux besoins particuliers des personnes en situation d'exclusion, défavorisées ou présentant des difficultés particulières ;",
    "4° Les réponses aux besoins particuliers des jeunes et des étudiants.",
    "III.- Après avis du comité régional de l'habitat et de l'hébergement d'Ile-de-France, l'État peut déléguer aux établissements publics de coopération intercommunale d'Ile-de-France l'attribution des aides à la pierre, dans les conditions prévues à l'article L. 301-5-1.",
], "Réécriture à droit constant : la mission du comité et la présidence sont formulées directement ; la longue phrase sur les objectifs du schéma est divisée entre objectifs globaux et déclinaison territoriale. Les collèges, les subdivisions et chaque domaine d'action sont conservés. Aucune réforme de fond.",
    "Conserver les cinq collèges, la durée de six ans, le 1er juillet 2014 et les lois n° 2010-597 du 3 juin 2010 et n° 2003-710 du 1er août 2003. La clause du 3° du I relative à l'attente de la création de la métropole reste reproduite malgré son caractère historique ; elle ne vaut pas nouvelle transition. Renvoi à L. 301-5-1 conservé. Le 5° du I conserve la chaîne d'énumération de la source, dont le rattachement grammatical des personnalités qualifiées à la représentation pourrait être clarifié par une coordination expresse.")

add('L302-14', [
    "I.- Le représentant de l'État dans la région communique au comité régional de l'habitat et de l'hébergement d'Ile-de-France toutes les informations utiles ainsi que les objectifs à prendre en compte en matière de diversité de l'habitat, de répartition équilibrée des différents types de logements, de renouvellement du parc immobilier et d'accroissement du nombre de logements et de places d'hébergement. Il le fait dans les trois mois suivant la transmission de la décision par laquelle le comité engage l'élaboration du schéma régional de l'habitat et de l'hébergement.",
    "Le comité régional de l'habitat et de l'hébergement d'Ile-de-France soumet son projet de schéma pour avis au conseil régional d'Ile-de-France, aux départements, à la métropole du Grand Paris, aux établissements publics de coopération intercommunale compétents en matière de programme local de l'habitat et aux communes qui n'appartiennent pas à de tels établissements. Ces collectivités et établissements disposent de trois mois à compter de la notification pour rendre leur avis.",
    "Au vu de ces avis, le comité régional de l'habitat et de l'hébergement délibère sur un nouveau projet de schéma. Il le soumet pour avis au représentant de l'État dans la région, dans les conditions prévues au deuxième alinéa du présent I.",
    "Le comité régional de l'habitat et de l'hébergement approuve le projet de schéma après l'avoir amendé pour tenir compte des demandes de modification que le représentant de l'État dans la région lui a, le cas échéant, adressées.",
    "Le représentant de l'État dans la région arrête le projet de schéma approuvé par le comité régional de l'habitat et de l'hébergement.",
    "II.- Lors de leur élaboration ou de leur révision, les contrats de développement territorial, le plan métropolitain de l'habitat et de l'hébergement et les programmes locaux de l'habitat prennent en compte le schéma régional de l'habitat et de l'hébergement.",
    "III.- Le schéma peut être révisé selon les modalités d'élaboration prévues au I du présent article.",
], "Réécriture à droit constant : chaque étape désigne son auteur et les deux délais de trois mois sont rattachés à leur point de départ. L'ordre des consultations, de l'approbation et de l'arrêt du schéma est maintenu, ainsi que les sept alinéas. Aucune réforme de fond.",
    "Les deux délais de trois mois et le renvoi au deuxième alinéa du I restent inchangés. La note source issue de l'article 7 de l'ordonnance n° 2020-745 du 17 juin 2020 vise les SCoT, PLU, documents en tenant lieu et cartes communales dont l'élaboration ou la révision est engagée à compter du 1er avril 2021. Son articulation avec cet article consacré au schéma régional de l'habitat et de l'hébergement appelle contrôle ; cette discordance apparente n'est ni corrigée ni utilisée pour dater la réforme.")

add('L302-15', [
    "Chaque année, le représentant de l'État dans la région établit un bilan de la programmation des aides au logement en Ile-de-France. À partir de ce bilan, le comité régional de l'habitat et de l'hébergement d'Ile-de-France coordonne les interventions de l'État, de la région d'Ile-de-France, des départements, de la métropole du Grand Paris et des établissements publics de coopération intercommunale compétents en matière de programme local de l'habitat, afin de favoriser la mise en œuvre du schéma régional de l'habitat et de l'hébergement.",
], "Réécriture à droit constant : la périodicité ouvre la disposition et le lien entre le bilan et la coordination des interventions est exprimé directement. L'attribut de présentation de la source est retiré. Aucune réforme de fond.",
    "Bilan annuel et ensemble des intervenants conservés. La coordination reste confiée au comité régional et demeure fondée sur le bilan établi par le représentant de l'État.")

add('L302-16', [
    "Les logements intermédiaires sont les logements qui remplissent les conditions suivantes, à l'exclusion des logements locatifs sociaux définis à l'article L. 302-5 :",
    "1° Ils bénéficient d'une aide directe ou indirecte, sous quelque forme que ce soit, accordée par l'État, une collectivité locale ou l'un de ses groupements, ou toute autre personne morale. Cette aide est subordonnée au respect, pendant une certaine durée, des conditions prévues aux 2° et 3° ;",
    "2° Ils sont destinés à être occupés à titre de résidence principale, pendant la durée fixée lors de l'attribution de l'aide mentionnée au 1°, par des personnes physiques dont les ressources n'excèdent pas des plafonds fixés par décret. Ces plafonds dépendent de la typologie du ménage, de la localisation et du mode d'occupation du logement. Pour les logements donnés en location, ils ne peuvent être inférieurs aux plafonds prévus au chapitre unique du titre III du livre III ;",
    "3° Pendant la durée mentionnée au 2°, leur prix d'acquisition ou, pour les logements donnés en location, leur loyer n'excède pas des plafonds fixés par décret. Ces plafonds dépendent de la localisation du logement, de son type et, le cas échéant, de son mode de financement. Pour les logements donnés en location, ils ne peuvent être inférieurs aux plafonds prévus au chapitre unique du titre III du livre III.",
], "Réécriture à droit constant : les trois conditions cumulatives sont formulées avec un sujet explicite ; les plafonds, leurs critères et leur limite inférieure font l'objet de phrases séparées. Aucune réforme de fond.",
    "Maintenir la distinction entre logements intermédiaires et logements sociaux de L. 302-5. Les deux renvois au chapitre unique du titre III du livre III concernent respectivement les plafonds de ressources et ceux de loyers ; ils fixent ici une limite inférieure, non supérieure. Ni taux, ni montant, ni durée supplémentaire ne sont créés.")

add('L302-16-1', [
    "La production et la mise en location de logements intermédiaires dont la livraison relève de l'article 279-0 bis A du code général des impôts donnent lieu à une information de l'administration. Cette obligation s'applique à partir du dépôt de la demande de permis de construire ou, en cas de vente en l'état futur d'achèvement, de l'acquisition. Elle se poursuit jusqu'à l'expiration de la période pendant laquelle un complément de taxe peut être dû conformément au II de l'article 284 du même code.<br/><br/>Un décret précise :<br/><br/>1° La personne morale tenue à cette information, parmi celle pour le compte de laquelle le logement est produit, le propriétaire du logement ou son gestionnaire ;<br/><br/>2° La périodicité de l'information et les conditions dans lesquelles l'administration peut demander des éléments complémentaires ;<br/><br/>3° Le contenu de l'information ;<br/><br/>4° Les modalités de cette information, notamment son format et ses conditions de transmission.",
], "Réécriture à droit constant : le début et la fin de l'obligation d'information sont exposés dans des phrases distinctes. Les quatre matières relevant du décret et le choix du débiteur parmi les trois personnes morales restent inchangés. Aucune réforme de fond.",
    "Renvois aux articles 279-0 bis A et 284, II, du CGI conservés. Selon la note source, l'article 50, III, de la loi n° 2020-1721 du 29 décembre 2020 limite l'application aux livraisons à compter du 1er janvier 2021, dans des opérations de construction ou de transformation sans agrément délivré sous la rédaction de l'article 279-0 bis A antérieure au 1er janvier 2021 : ne pas étendre le régime aux opérations agréées antérieurement. La version assignée est marquée ABROGE_DIFF, avec fin de validité au 1er janvier 2027 ; coordonner cette extinction avec L. 302-16-2 et les textes fiscaux, sans la supprimer ni inventer un régime de remplacement.")

add('L302-16-2', [
    "Les manquements à l'obligation prévue à l'article L. 302-16-1 sont sanctionnés par les amendes suivantes, appréciées pour chaque ensemble immobilier :<br/><br/>1° Une amende de 1 500 € dans chacun des cas suivants :<br/><br/>a) L'information n'est pas communiquée ou l'est au-delà du premier jour du deuxième mois suivant l'échéance fixée par le décret mentionné à l'article L. 302-16-1 ;<br/><br/>b) L'information comporte une inexactitude ou une omission résultant d'un manquement délibéré ou de manœuvres frauduleuses ;<br/><br/>2° Une amende de 500 € lorsque l'information n'est pas produite à l'échéance prévue, dans les situations autres que celles mentionnées au a du 1° du présent article.<br/><br/>Ces amendes sont recouvrées selon les mêmes procédures et sous les mêmes sanctions, garanties, sûretés et privilèges que la taxe sur les salaires. Les réclamations sont présentées, instruites et jugées selon les règles applicables à cette taxe.<br/><br/>Les services qui reçoivent l'information prévue à l'article L. 302-16-1 du présent code communiquent à l'administration fiscale tout élément utile au contrôle de l'application des articles 279-0 bis A et 1384-0 A du code général des impôts.",
], "Réécriture à droit constant : les faits sanctionnés sont formulés directement et chaque montant est rattaché à son cas d'application. Le régime de recouvrement, les réclamations et la transmission fiscale sont intégralement maintenus. Aucune réforme de fond.",
    "Amendes de 1 500 € et 500 €, appréciation par ensemble immobilier et seuil du premier jour du deuxième mois conservés. Le b du 1° reste limité au manquement délibéré ou aux manœuvres frauduleuses. La note source de l'article 50, III, de la loi n° 2020-1721 du 29 décembre 2020 réserve le régime aux livraisons à compter du 1er janvier 2021 dans les opérations de construction ou transformation non agréées selon la rédaction de l'article 279-0 bis A antérieure au 1er janvier 2021. Version ABROGE_DIFF jusqu'au 1er janvier 2027 : articuler l'extinction avec L. 302-16-1 et le traitement des manquements antérieurs. Les renvois fiscaux et le régime de la taxe sur les salaires ne sont pas remplacés.")

add('L302-17', [
    "Chaque commune dispose d'un plan local de lutte contre l'habitat indigne. Ce plan est élaboré à l'initiative de la commune ou, lorsque l'établissement public de coopération intercommunale dont elle est membre est tenu d'élaborer un programme local de l'habitat en application de l'article L. 302-1, à l'initiative de cet établissement. Le volet relatif à l'habitat indigne du programme local de l'habitat prévu au III du même article L. 302-1 comprend les éléments énumérés à l'article L. 302-18.",
    "Le plan local de lutte contre l'habitat indigne fixe, pour six ans, les objectifs et les actions prioritaires nécessaires à la résorption de l'habitat indigne et informel. Il repose sur un diagnostic des différentes formes de ces habitats mentionnées à l'article 1er-1 de la loi n° 90-449 du 31 mai 1990 visant à la mise en œuvre du droit au logement.",
    "Lorsqu'une commune membre d'un établissement public de coopération intercommunale compétent en matière de programme local de l'habitat a élaboré un plan communal de lutte contre l'habitat indigne, ce plan est intégré au programme local de l'habitat. Il en constitue le volet relatif à l'habitat indigne pour cette commune.",
    "Par dérogation à la section 1 du présent chapitre, un établissement public de coopération intercommunale peut engager et approuver un plan intercommunal de lutte contre l'habitat indigne. Ce plan est intégré au programme local de l'habitat lors de la finalisation de ce dernier.",
], "Réécriture à droit constant : l'initiative du plan, son diagnostic et son intégration au programme local de l'habitat sont formulés en phrases distinctes, en maintenant les quatre alinéas logiques de la source. Aucune réforme de fond.",
    "Cet article relève de la section 6 relative à la Guadeloupe, à la Guyane, à la Martinique, à La Réunion, à Mayotte et à Saint-Martin : ne pas généraliser son champ territorial. Durée de six ans, renvois à L. 302-1, III, à L. 302-18, à la section 1 et à l'article 1er-1 de la loi n° 90-449 du 31 mai 1990 conservés. L'intégration intervient à la finalisation du programme pour le plan intercommunal engagé séparément.")

add('L302-18', [
    "Le plan local de lutte contre l'habitat indigne comprend les éléments suivants :",
    "1° Un repérage exhaustif des différentes formes d'habitat indigne et informel sur le territoire de la commune ou des communes comprises dans le périmètre de l'établissement public de coopération intercommunale. Ce repérage indique l'état technique et sanitaire des locaux d'habitation et leur localisation au regard des risques naturels. Il mentionne aussi, le cas échéant, la situation des constructions au regard de la propriété du terrain d'assiette ;",
    "2° Des objectifs quantitatifs et qualitatifs de traitement de l'habitat indigne et informel, définis au vu des différentes situations analysées, tant pour la politique urbaine que pour la politique sociale ;",
    "3° Les priorités d'action pour la durée du programme, accompagnées d'un calendrier prévisionnel. Ces priorités résultent de l'analyse des urgences sanitaires et sociales, qui inclut les situations de grave exposition aux risques naturels ;",
    "4° Les moyens techniques, humains et financiers à mettre en œuvre, ainsi que la programmation des procédures juridiques et opérationnelles à engager pour traiter les urgences repérées ;",
    "5° Les modalités de mise en œuvre, de pilotage et d'évaluation du programme.",
    "Les communes ou l'établissement public de coopération intercommunale concerné et l'État signent un protocole d'accord pour la mise en œuvre du plan local de lutte contre l'habitat indigne. Ce protocole associe, le cas échéant, d'autres collectivités ou organismes publics. Il précise les objectifs et les actions à engager pendant la durée du plan.",
], "Réécriture à droit constant : les cinq éléments obligatoires du plan sont exprimés directement, et les informations du repérage comme les engagements du protocole sont divisés en phrases plus courtes. Aucune réforme de fond.",
    "Champ territorial de la section 6 maintenu. Le repérage demeure exhaustif ; l'état technique et sanitaire, les droits sur le terrain d'assiette le cas échéant, les risques naturels, les urgences, les trois catégories de moyens et l'évaluation restent requis. Aucun chiffrage de financement n'est ajouté ; le calendrier demeure prévisionnel.")

add('L302-19', [
    "Lorsqu'une commune ou un établissement public de coopération intercommunale engage un plan communal ou intercommunal de lutte contre l'habitat indigne indépendamment de l'élaboration d'un programme local de l'habitat, ce plan est soumis aux dispositions de l'article L. 302-2 relatives aux modalités d'élaboration du programme, à l'association des personnes publiques et à son approbation.",
], "Réécriture à droit constant : le plan devient le sujet explicite de l'application des règles procédurales de L. 302-2. La condition d'une élaboration indépendante du programme local de l'habitat est maintenue. Aucune réforme de fond.",
    "Le renvoi reste limité aux règles de L. 302-2 concernant l'élaboration, l'association des personnes publiques et l'approbation ; il ne transpose pas indistinctement tout cet article. Respecter le champ territorial de la section 6.")

add('L303-1', [
    "Les opérations programmées d'amélioration de l'habitat visent à réhabiliter le parc immobilier bâti. Elles tendent à améliorer l'offre de logements, en particulier locatifs, ainsi qu'à maintenir ou à développer les services de voisinage. Leur mise en œuvre respecte les équilibres sociaux, la sauvegarde du droit des occupants, les objectifs du plan départemental d'action pour le logement et l'hébergement des personnes défavorisées et, s'il existe, ceux du programme local de l'habitat. Ces opérations donnent lieu à une convention entre, d'une part, la commune ou l'établissement public de coopération intercommunale compétent en matière d'habitat, ou le syndicat mixte mandaté par ces derniers, et, d'autre part, l'Agence nationale de l'habitat et l'État.",
    "La convention précise :",
    "a) Le périmètre de l'opération ;",
    "b) Le montant total des aides susceptibles d'être accordées par l'Agence nationale de l'habitat, l'État et, le cas échéant, la commune ou l'établissement public de coopération intercommunale ou d'autres personnes publiques ou privées. Ces aides concernent l'amélioration de l'habitat, la construction de logements sociaux, l'acquisition de logements à améliorer pour un usage locatif social, les baux à réhabilitation et les actions d'accompagnement prévues ;",
    "c) Les actions d'accompagnement et d'amélioration du cadre de vie prévues par l'État, la commune ou l'établissement public de coopération intercommunale ;",
    "d) Les actions visant à respecter la diversité de la population dans les quartiers, à maintenir le caractère social de l'occupation des logements et à favoriser le maintien sur place des occupants ;",
    "e) Les actions visant à maintenir ou à implanter des services ou des équipements commerciaux ou artisanaux de proximité.",
    "Le projet de convention est mis à la disposition du public pendant un mois avant sa signature.",
    "Une fois signée, la convention est consultable en mairie pendant toute sa durée de validité.",
    "Lorsqu'un département ou un établissement public de coopération intercommunale a conclu avec l'État une convention en application des articles L. 301-5-1 ou L. 301-5-2, son représentant signe les conventions prévues au présent article en lieu et place du représentant de l'État et de l'Agence nationale de l'habitat, dans les conditions fixées par les conventions conclues au titre de ces articles.",
], "Réécriture à droit constant : les parties à la convention, les objets des aides et les règles de publicité sont formulés directement. Les lettres a à e et leur emplacement sont maintenus pour les renvois, notamment celui de L. 303-2. Aucune réforme de fond.",
    "Publicité préalable d'un mois, consultation pendant toute la validité et substitution de signature au titre de L. 301-5-1 ou L. 301-5-2 conservées. Les aides restent seulement susceptibles d'être accordées, sans montant nouveau. Le droit des occupants et le maintien sur place restent des exigences de l'opération. Pour la voie locative de rénovation de vingt-quatre mois prévue par policy.json, une intervention distincte est nécessaire dans la loi n° 89-462 du 6 juillet 1989, notamment ses articles 6 et 20-1, et dans le décret n° 2002-120 du 30 janvier 2002 sur la décence : définir les biens éligibles, le contrôle des travaux et la compensation des surcoûts énergétiques. Cette convention ne peut à elle seule autoriser la location d'un logement exclu de la location ; aucun renvoi à un dispositif encore inexistant n'est créé.")

add('L303-1-1', [
    "Lorsqu'un immeuble ou un ensemble immobilier soumis au statut de la copropriété des immeubles bâtis est compris dans le périmètre d'une opération programmée d'amélioration de l'habitat prévue à l'article L. 303-1, la procédure suivante peut être engagée si cette opération poursuit un objectif de redressement et de transformation des copropriétés dégradées et si sa poursuite nécessite la division du syndicat des copropriétaires ou la création de syndicats de copropriétaires secondaires. Le représentant de l'État dans le département ou, avec son accord, l'une des collectivités territoriales signataires de la convention prévue au même article L. 303-1 peut demander au syndic d'inscrire le projet de division ou de création de syndicats secondaires à l'ordre du jour de la prochaine assemblée générale.",
    "Le premier alinéa du présent article s'applique uniquement aux opérations qui prévoient à la fois des dispositifs d'accompagnement social des occupants et des propriétaires et des dispositifs d'intervention immobilière et foncière comprenant des actions d'acquisition, de travaux et de portage de lots de copropriété. L'état de dégradation de l'immeuble doit en outre compromettre sa conservation. Un rapport d'expert constate cet état ; il est établi aux frais de l'État ou de l'une des collectivités signataires de la convention.",
    "Si l'assemblée des copropriétaires n'adopte pas le projet de division du syndicat ou de création de syndicats secondaires, le syndic en informe les signataires de la convention.",
    "Dès réception de cette information, le représentant de l'État dans le département signataire de la convention ou, avec son accord, l'une des collectivités territoriales signataires peut, après avis des autres signataires, saisir le juge afin qu'il :",
    "1° Constate que cette abstention compromet à la fois la poursuite de l'opération programmée d'amélioration de l'habitat prévue à l'article L. 303-1 et la conservation de l'immeuble compris dans son périmètre ;",
    "2° Désigne, aux frais du demandeur, un expert chargé de la mission prévue à l'article L. 741-3.",
    "Le demandeur exerce alors le rôle que l'article L. 741-3 confie à l'opérateur d'opération de requalification des copropriétés dégradées. Il peut déléguer ce rôle à un opérateur. La division ne peut entraîner le partage inégal prévu au V du même article L. 741-3.",
], "Réécriture à droit constant : les conditions cumulatives de recours à la procédure, l'accord préfectoral et les deux étapes d'expertise sont rendus explicites. La saisine du juge, la numérotation et l'interdiction du partage inégal sont conservées. Les attributs de présentation sont supprimés ; aucune réforme de fond.",
    "Le contrôle porte sur la conservation de l'immeuble et la poursuite de l'opération, non sur un seul de ces critères. Le premier rapport est payé par l'État ou une collectivité signataire ; l'expertise judiciaire l'est par le demandeur. Renvoi à L. 741-3 vérifié dans le corpus : son V prévoit effectivement un partage inégal indemnisé, que le présent article exclut expressément. L'accord du préfet reste requis pour l'initiative d'une collectivité, et l'avis des autres signataires pour la saisine du juge ; l'assemblée générale préalable n'est pas supprimée.")

add('L303-2', [
    "I.- Les opérations de revitalisation de territoire mettent en œuvre un projet global de territoire destiné à adapter et à moderniser le parc de logements, les locaux commerciaux et artisanaux et le tissu urbain. Ce projet vise à améliorer l'attractivité du territoire, à lutter contre la vacance des logements et des locaux commerciaux et artisanaux ainsi que contre l'habitat indigne, à réhabiliter l'immobilier de loisir, à valoriser le patrimoine bâti et à réhabiliter les friches urbaines, dans une perspective de mixité sociale, d'innovation et de développement durable. Un secteur d'intervention comprenant une entrée de ville ou une zone commerciale périphérique doit être distinct des secteurs comprenant un centre-ville.",
    "Ces opérations font l'objet d'une convention entre l'État, ses établissements publics intéressés, un établissement public de coopération intercommunale à fiscalité propre et tout ou partie de ses communes membres, ainsi que toute personne publique ou tout acteur privé susceptible de les soutenir ou de participer à la réalisation des opérations prévues par la convention.",
    "Une entité mentionnée au deuxième alinéa du présent article ne peut signer la convention que si son adhésion n'est pas susceptible de la placer ultérieurement en situation de conflit d'intérêts.",
    "II.- La convention définit le projet urbain, économique et social de revitalisation du territoire concerné. Ce projet favorise la mixité sociale, le développement durable, la valorisation du patrimoine et l'innovation. La convention délimite les secteurs d'intervention, qui comprennent nécessairement le centre-ville de la ville principale du territoire de l'établissement public de coopération intercommunale à fiscalité propre signataire. Leur périmètre peut aussi comprendre un ou plusieurs centres-villes d'autres communes membres de cet établissement et des parties déjà urbanisées de toute commune membre.",
    "La convention fixe sa durée, le calendrier et le plan de financement des actions prévues, ainsi que leur répartition entre les secteurs d'intervention délimités. Elle précise aussi les conditions de délégation de ces actions à des opérateurs.",
    "Le cas échéant, l'établissement public de coopération intercommunale à fiscalité propre concerné engage une concertation publique avant la signature de la convention mentionnée au deuxième alinéa du I du présent article.",
    "III.- Une convention d'opération de revitalisation de territoire comprend tout ou partie des actions d'amélioration de l'habitat prévues à l'article L. 303-1. Si elle comprend toutes les dispositions mentionnées aux a à e du même article L. 303-1, elle tient lieu de convention d'opération programmée d'amélioration de l'habitat au sens de l'article L. 303-1.",
    "La convention d'opération de revitalisation de territoire prévoit aussi tout ou partie des actions suivantes :",
    "1° Un dispositif d'intervention immobilière et foncière contribuant à revaloriser les îlots d'habitat vacant ou dégradé et comprenant notamment des actions d'acquisition, de travaux et de portage de lots de copropriété ;",
    "2° Un plan de relogement et d'accompagnement social des occupants, dont l'objectif prioritaire est leur maintien dans le même quartier requalifié ;",
    "3° Le recours aux dispositifs coercitifs de lutte contre l'habitat indigne ;",
    "4° Des actions en faveur de la transition énergétique du territoire, notamment pour améliorer la performance énergétique du parc immobilier et végétaliser les espaces urbains et les bâtiments ;",
    "5° Un projet social comprenant notamment des actions en faveur de la mixité sociale et de l'adaptation de l'offre de logement, de services publics et de services de santé aux personnes en perte d'autonomie ;",
    "6° Des actions ou opérations d'aménagement, au sens de l'article L. 300-1 du code de l'urbanisme, qui contribuent à l'aménagement des espaces et des équipements publics de proximité. Elles prennent en compte les problèmes d'accessibilité, de desserte des commerces et des locaux artisanaux de centre-ville et de mobilité, ainsi que l'objectif de localisation des commerces en centre-ville ;",
    "7° Des dispositifs d'intervention immobilière et foncière visant à reconvertir ou à réhabiliter les sites industriels et commerciaux vacants ainsi que les sites administratifs et militaires déclassés. Ces dispositifs peuvent également porter sur la transformation en logements de bureaux ou d'autres locaux, lorsqu'ils sont vacants. Pour ces transformations, les conventions conclues après l'expiration d'un délai de six mois à compter de l'entrée en vigueur des présentes dispositions organisent un dossier commun et la coordination des démarches auprès des services compétents. Les services réutilisent les pièces qu'ils détiennent déjà légalement lorsque cette réutilisation est autorisée, dans le respect des secrets protégés et du droit de rectification des données. Ils ne demandent pas à nouveau au porteur du projet les pièces ainsi réutilisées. Les autorisations requises, les compétences de chaque autorité et les délais d'instruction applicables sont maintenus ;",
    "8° Des actions visant à moderniser ou à créer des activités ou des animations économiques, commerciales, artisanales, touristiques ou culturelles, sous la responsabilité d'un opérateur ;",
    "9° Des actions ou opérations favorisant, en particulier en centre-ville, la création, l'extension, la transformation ou la reconversion de surfaces commerciales ou artisanales ;",
    "10° L'engagement de la ou des autorités compétentes en matière de plan local d'urbanisme, de document d'urbanisme en tenant lieu ou de carte communale de modifier les documents d'urbanisme, approuvés ou en cours d'approbation, dans la mesure nécessaire à la réalisation des plans, projets ou actions prévus par la convention. Si cette compétence est transférée à l'établissement public de coopération intercommunale en application de l'avant-dernier alinéa de l'article L. 5211-17 du code général des collectivités territoriales, cet établissement se substitue à la ou aux communes ayant pris cet engagement ;",
    "11° Des actions ou opérations de requalification ou d'amélioration des entrées de ville ou des zones commerciales périphériques, sans porter atteinte aux commerces de centre-ville. Elles contribuent à la mixité fonctionnelle, à l'optimisation de l'usage de la ressource foncière, à une meilleure insertion architecturale et paysagère des bâtiments, à l'amélioration des espaces publics et au développement des modes de déplacement les moins émetteurs de gaz à effet de serre. Elles ne doivent pas augmenter la consommation d'espaces naturels, agricoles et forestiers.",
    "Par dérogation au chapitre V du titre IV du livre Ier du code de commerce, la convention peut aussi prévoir, dans les centres-villes mentionnés au II du présent article, les règles suivantes :",
    "a) Dans les immeubles comprenant à la fois un ou plusieurs locaux commerciaux et des locaux destinés à l'habitation, les baux portant sur un local commercial et conclus après la signature de la convention ne peuvent porter que sur ce local. Cette limitation ne concerne ni les locaux destinés au fonctionnement des activités commerciales ou artisanales, ni le local d'habitation occupé par le commerçant ou l'artisan qui exerce son activité professionnelle en rez-de-chaussée ;",
    "b) Après la signature de la convention, les travaux qui condamnent, dans un même immeuble, l'accès indépendant à des locaux ayant une destination distincte de l'activité commerciale ou artisanale sont interdits.",
    "L'opération de revitalisation de territoire peut permettre l'instauration du droit de préemption urbain renforcé prévu à l'article L. 211-4 du code de l'urbanisme et du droit de préemption sur les fonds artisanaux, les fonds de commerce, les baux commerciaux et les terrains faisant l'objet de projets d'aménagement commercial prévu à l'article L. 214-1 du même code. Le droit de préemption urbain, y compris sa forme renforcée dans les conditions prévues à l'article L. 211-4, et le droit de préemption sur les fonds artisanaux, les fonds de commerce, les baux commerciaux et les terrains faisant l'objet de projets d'aménagement commercial peuvent être délégués dans les conditions prévues aux articles L. 211-2-3 et L. 214-1-1 du même code.",
    "Les actions prévues par une convention de revitalisation de territoire peuvent être inscrites parmi celles des contrats de plan prévus à l'article 11 de la loi n° 82-653 du 29 juillet 1982 portant réforme de la planification.",
    "Un bilan annuel et une évaluation tous les cinq ans des actions entreprises dans le cadre de l'opération de revitalisation de territoire et de leurs incidences financières sont présentés aux conseils municipaux des communes signataires et à l'organe délibérant de l'établissement public de coopération intercommunale à fiscalité propre signataire de la convention.",
], "Réécriture à droit constant de la définition, des parties à la convention, des actions, des règles commerciales, de la préemption et de l'évaluation : les auteurs et les conditions sont explicités dans les mêmes subdivisions. Réforme de fond limitée au 7° du III, conformément à policy.json : les transformations de bureaux et de locaux vacants en logements sont expressément incluses et les nouvelles conventions organisent un dossier commun, la coordination des démarches et le réemploi légal des pièces sans demande en double. L'application à ces conventions intervient après les six mois d'organisation des services retenus dans coordination.json. Cette réforme conserve les autorisations, les compétences et les délais applicables.",
    "Les I à III, les 1° à 11°, les a et b, les alinéas et tous les renvois de la source sont conservés à leur place. Les clauses commerciales restent limitées aux baux conclus ou aux travaux effectués après la signature de la convention, avec les deux exceptions du a ; aucune extension aux baux anciens. La coordination nouvelle du 7° concerne les conventions conclues après les six mois suivant l'entrée en vigueur de la réforme, sans date de promulgation inventée et sans réécriture automatique des conventions antérieures. Le délai de six mois reprend la transition organisationnelle retenue pour L. 423-1 du code de l'urbanisme dans coordination.json ; assurer une même entrée en vigueur des dispositions coordonnées. Le dossier commun ne crée ni autorisation unique ni délai abrégé. Pour les solutions techniques équivalentes, les articles L. 112-4, L. 112-6 et L. 112-9 à L. 112-12 du CCH, vérifiés dans le corpus, constituent les dispositions pertinentes hors lot ; maintenir la preuve des résultats, les attestations et le contrôle en matière de sécurité, d'accessibilité et de salubrité. La rénovation locative de vingt-quatre mois exige des dispositions dans les articles 6 et 20-1 de la loi n° 89-462 du 6 juillet 1989 et le décret n° 2002-120 du 30 janvier 2002 ; l'accélération judiciaire des impayés appelle notamment l'article 24 de cette loi et les règles procédurales applicables hors des cinq codes, sans autoriser d'expulsion privée. La convention ne déroge pas aux obligations de logement social. Conserver le bilan annuel, l'évaluation quinquennale et l'interdiction d'augmenter la consommation d'espaces naturels, agricoles et forestiers ; aucun financement ni résultat chiffré n'est présumé.")

add('L303-3', [
    "Par dérogation accordée par le représentant de l'État dans le département, une opération de revitalisation de territoire peut être conclue sur le périmètre d'une ou de plusieurs communes membres d'un établissement public de coopération intercommunale à fiscalité propre, sans inclure la ville principale de cet établissement au sens de l'article L. 303-2. La dérogation est subordonnée aux deux conditions suivantes :<br/><br/>1° Le périmètre présente une discontinuité territoriale ou un éloignement par rapport à la ville principale de l'établissement public de coopération intercommunale à fiscalité propre ;<br/><br/>2° Une ou plusieurs villes présentant des caractéristiques de centralité sont identifiées dans ce périmètre. Ces caractéristiques sont appréciées notamment au regard de la diversité des fonctions urbaines exercées en matière d'équipements et de services pour les communes alentour.<br/><br/>La convention d'opération de revitalisation de territoire est signée par l'établissement public de coopération intercommunale à fiscalité propre, la commune concernée et l'État. Toute autre commune de cet établissement, ainsi que les organismes publics ou privés susceptibles de soutenir l'opération ou de participer à sa réalisation, peuvent également la signer.",
], "Réécriture à droit constant : la dérogation préfectorale est placée en tête et les deux conditions cumulatives sont rattachées explicitement au périmètre. Les signataires obligatoires et facultatifs sont distingués. Aucune réforme de fond.",
    "Les deux conditions du 1° et du 2° restent cumulatives ; à l'intérieur du 1°, la discontinuité et l'éloignement demeurent alternatifs. La dérogation ne dispense que d'inclure la ville principale au sens de L. 303-2. La source vise plusieurs communes possibles mais emploie au dernier alinéa le singulier « la commune concernée » pour la signature obligatoire : formulation conservée, articulation à contrôler pour une opération pluricommunale.")

add('L311-1', [
    "Les logements dont le titre d'occupation est un accessoire du contrat de travail ne peuvent bénéficier des primes à la construction d'habitations. Par exception, les collectivités locales et les établissements publics bénéficient de ces primes pour tout logement à usage d'habitation qu'ils construisent ou aménagent, à condition qu'aucune subvention de l'État ne leur soit versée pour ce logement.",
    "Un décret fixe les conditions dans lesquelles certains logements destinés à des salariés agricoles peuvent échapper à cette règle.",
], "Réécriture à droit constant : l'exclusion des logements liés au contrat de travail et l'exception applicable aux collectivités et établissements publics font l'objet de deux phrases. L'exception réglementaire agricole demeure autonome. Aucune réforme de fond.",
    "L'absence de subvention de l'État reste appréciée pour le logement en cause et conditionne l'exception des collectivités locales et établissements publics. Ne pas supprimer ce régime historique ni étendre automatiquement l'exception aux autres employeurs ; les conditions propres aux salariés agricoles restent fixées par décret.")

add('L311-2', [
    "Pour le remboursement des primes accordées afin de favoriser la construction d'habitations, les organismes d'habitations à loyer modéré peuvent accepter les effets émis au profit du Comptoir des entrepreneurs. Le Crédit foncier de France et le Comptoir des entrepreneurs sont subrogés dans l'hypothèque prise par les sociétés de crédit immobilier pour garantir leurs avances. Il s'agit des avances que ces sociétés consentent au moyen des prêts accordés par ces deux prêteurs.",
], "Réécriture à droit constant : la faculté d'accepter les effets est formulée séparément, puis la désignation des avances garanties est détachée de la règle de subrogation. Aucune obligation nouvelle de constituer une hypothèque ni actualisation des organismes historiques n'est introduite.",
    "Conserver le caractère facultatif de l'acceptation des effets, leur émission au profit du Comptoir des entrepreneurs et la subrogation du Crédit foncier de France et du Comptoir des entrepreneurs. Les dénominations et mécanismes anciens sont conservés pour les situations auxquelles ils restent applicables ; leur actualisation exige une coordination distincte, sans substitution silencieuse d'un organisme actuel.")

add('L311-3', [
    "Pendant toute la période de versement des primes, les locaux dont la création a bénéficié de ces primes ne peuvent être transformés en locaux commerciaux ni affectés à la location saisonnière.",
    "Dans tout acte entraînant la mutation ou la location de l'immeuble, le propriétaire doit déclarer l'existence des interdictions prévues à l'alinéa précédent.",
    "Toute personne qui contrevient au présent article encourt une amende de 45 000 euros.",
    "En outre, les primes perçues depuis la transformation doivent être restituées.",
], "Réécriture à droit constant : la durée des interdictions figure en tête, l'obligation déclarative du propriétaire est exprimée directement et la répétition des primes est formulée comme une restitution. Les quatre alinéas sont conservés ; aucune réforme de fond.",
    "Amende de 45 000 euros, interdictions pendant le versement, déclaration dans tout acte de mutation ou de location et répétition depuis la transformation conservées. La source rattache expressément la répétition à la transformation sans mentionner séparément l'affectation à la location saisonnière : cette asymétrie préexistante reste inchangée et appelle contrôle. La politique de remise en location n'efface pas les conditions attachées à ces primes historiques.")

add('L311-4', [
    "Dans la limite des crédits prévus, les collectivités locales et les établissements publics bénéficient, pour les logements qu'ils construisent, des primes à la construction instituées par les dispositions réglementaires prises pour l'application de la présente section.",
], "Réécriture à droit constant : les bénéficiaires et la limite budgétaire sont placés avant la désignation du régime de primes. Aucun droit sans crédits ni réforme de fond n'est ajouté.",
    "Maintenir la limite des crédits prévus, le renvoi aux dispositions réglementaires de la présente section et le champ des logements construits par les collectivités locales ou établissements publics. Aucun budget nouveau n'est fixé.")

add('L311-5', [
    "Toute personne qui tente d'obtenir les primes par de fausses déclarations ou des manœuvres frauduleuses encourt une amende de 45 000 euros.",
], "Réécriture à droit constant : l'auteur de la tentative, les moyens frauduleux et la sanction sont exprimés en termes directs. La tentative reste punissable sans obtention effective des primes. Aucune réforme de fond.",
    "Montant de 45 000 euros conservé. Les fausses déclarations et les manœuvres frauduleuses restent deux moyens alternatifs ; l'infraction ne se limite pas à la perception effective d'une prime.")


assert len(sources) == 24
assert len(drafts) == 24
assert set(drafts) == {a['number'] for a in sources}
answer = []
for source in sources:
    item = {key: source[key] for key in ('code_id', 'source_id', 'source_sha256', 'number')}
    item.update(drafts[source['number']])
    item['status'] = 'rewrite_draft'
    answer.append(item)
Path('answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
